package keystrokesmod.script.packet.serverbound;
import keystrokesmod.script.model.Entity; import keystrokesmod.script.model.Vec3; import net.minecraft.network.play.client.C02PacketUseEntity;
public class C02 extends CPacket { public Entity entity; public String action; public Vec3 hitVec; public C02(Entity entity,String action,Vec3 hit){super(create(entity,action,hit));this.entity=entity;this.action=action;hitVec=hit;} public C02(C02PacketUseEntity value){super(value);entity=Entity.convert(value.getEntityFromWorld(net.minecraft.client.Minecraft.getMinecraft().theWorld));action=value.getAction().name();} private static C02PacketUseEntity create(Entity entity,String action,Vec3 hit){C02PacketUseEntity.Action value=C02PacketUseEntity.Action.valueOf(action.toUpperCase(java.util.Locale.ROOT));return value==C02PacketUseEntity.Action.INTERACT_AT?new C02PacketUseEntity(entity.entity,Vec3.getVec3(hit)):new C02PacketUseEntity(entity.entity,value);} public C02PacketUseEntity convert(){return (C02PacketUseEntity)packet;} }
